#include <Wire.h>
#include <LiquidCrystal_I2C.h>

/*
  ==========================================
               FOOD QUEST
          ARDUINO CONTROLLER
  ==========================================

  Arduino = controle físico.

  Ele NÃO sabe as perguntas.
  Ele NÃO controla o jogo.

  Ele:
  - lê joystick;
  - lê botões;
  - controla LCD;
  - controla LEDs;
  - conversa com o celular.
*/


/* ==========================================
   LCD
========================================== */

LiquidCrystal_I2C lcd(0x27, 16, 2);


/* ==========================================
   PINOS
========================================== */

const int JOY_X = A0;
const int JOY_Y = A1;

const int BUTTON_OK   = 2;
const int BUTTON_HINT = 3;

/*
  Apertar o próprio joystick
  funciona como BACK.
*/
const int BUTTON_BACK = 4;

const int LED_GREEN = 8;
const int LED_RED   = 9;


/* ==========================================
   JOYSTICK
========================================== */

const int LOW_LIMIT  = 300;
const int HIGH_LIMIT = 700;

bool joystickReleased = true;


/* ==========================================
   BOTÕES
========================================== */

bool oldOK   = HIGH;
bool oldHint = HIGH;
bool oldBack = HIGH;

unsigned long lastButtonTime = 0;

const unsigned long debounceTime = 180;


/* ==========================================
   SERIAL RECEBIDA DO CELULAR
========================================== */

String serialLine = "";


/* ==========================================
   SETUP
========================================== */

void setup() {

  Serial.begin(9600);


  /* BOTÕES */

  pinMode(
    BUTTON_OK,
    INPUT_PULLUP
  );

  pinMode(
    BUTTON_HINT,
    INPUT_PULLUP
  );

  pinMode(
    BUTTON_BACK,
    INPUT_PULLUP
  );


  /* LEDs */

  pinMode(
    LED_GREEN,
    OUTPUT
  );

  pinMode(
    LED_RED,
    OUTPUT
  );


  digitalWrite(
    LED_GREEN,
    LOW
  );

  digitalWrite(
    LED_RED,
    LOW
  );


  /* LCD */

  lcd.init();

  lcd.backlight();

  showLCD(
    "FOOD QUEST",
    "AGUARDANDO..."
  );


  delay(500);

}


/* ==========================================
   LOOP
========================================== */

void loop() {

  readJoystick();

  readButtons();

  readPhone();

}


/* ==========================================
   JOYSTICK
========================================== */

void readJoystick() {

  int x =
    analogRead(JOY_X);

  int y =
    analogRead(JOY_Y);


  /*
     Centro do joystick
  */

  if(
    x > LOW_LIMIT &&
    x < HIGH_LIMIT &&
    y > LOW_LIMIT &&
    y < HIGH_LIMIT
  ) {

    joystickReleased = true;

    return;

  }


  /*
     Só envia um movimento
     até voltar ao centro.
  */

  if(!joystickReleased)
    return;


  /*
     CIMA
  */

  if(y < LOW_LIMIT) {

    Serial.println(
      "JOY_UP"
    );

    joystickReleased = false;

    return;

  }


  /*
     BAIXO
  */

  if(y > HIGH_LIMIT) {

    Serial.println(
      "JOY_DOWN"
    );

    joystickReleased = false;

    return;

  }


  /*
     ESQUERDA
  */

  if(x < LOW_LIMIT) {

    Serial.println(
      "JOY_LEFT"
    );

    joystickReleased = false;

    return;

  }


  /*
     DIREITA
  */

  if(x > HIGH_LIMIT) {

    Serial.println(
      "JOY_RIGHT"
    );

    joystickReleased = false;

    return;

  }

}


/* ==========================================
   BOTÕES
========================================== */

void readButtons() {

  bool nowOK =
    digitalRead(
      BUTTON_OK
    );

  bool nowHint =
    digitalRead(
      BUTTON_HINT
    );

  bool nowBack =
    digitalRead(
      BUTTON_BACK
    );


  /*
    Botão A
    OK / START / CONFIRMAR
  */

  if(
    oldOK == HIGH &&
    nowOK == LOW &&
    canPress()
  ) {

    Serial.println(
      "BUTTON_OK"
    );

    buttonPressed();

  }


  /*
    Botão B
    DICA
  */

  if(
    oldHint == HIGH &&
    nowHint == LOW &&
    canPress()
  ) {

    Serial.println(
      "BUTTON_HINT"
    );

    buttonPressed();

  }


  /*
    Clique do joystick
    VOLTAR
  */

  if(
    oldBack == HIGH &&
    nowBack == LOW &&
    canPress()
  ) {

    Serial.println(
      "BUTTON_BACK"
    );

    buttonPressed();

  }


  oldOK =
    nowOK;

  oldHint =
    nowHint;

  oldBack =
    nowBack;

}


/* ==========================================
   DEBOUNCE
========================================== */

bool canPress() {

  return
    millis() -
    lastButtonTime
    >
    debounceTime;

}


void buttonPressed() {

  lastButtonTime =
    millis();

}


/* ==========================================
   RECEBER MENSAGENS
   DO CELULAR
========================================== */

void readPhone() {

  while(
    Serial.available()
  ) {

    char c =
      Serial.read();


    if(c == '\n') {

      serialLine.trim();

      if(
        serialLine.length() > 0
      ) {

        processPhoneCommand(
          serialLine
        );

      }

      serialLine = "";

    }

    else {

      serialLine += c;

    }

  }

}


/* ==========================================
   COMANDOS DO CELULAR
========================================== */

void processPhoneCommand(
  String command
) {


  /*
    ---------------------------------
    LCD

    Exemplo recebido:

    LCD|RAFAEL:|DE UMA DICA
    ---------------------------------
  */

  if(
    command.startsWith(
      "LCD|"
    )
  ) {

    processLCDCommand(
      command
    );

    return;

  }


  /*
    LED VERDE
  */

  if(
    command ==
    "LED|GREEN"
  ) {

    digitalWrite(
      LED_GREEN,
      HIGH
    );

    digitalWrite(
      LED_RED,
      LOW
    );

    return;

  }


  /*
    LED VERMELHO
  */

  if(
    command ==
    "LED|RED"
  ) {

    digitalWrite(
      LED_GREEN,
      LOW
    );

    digitalWrite(
      LED_RED,
      HIGH
    );

    return;

  }


  /*
    APAGAR LEDs
  */

  if(
    command ==
    "LED|OFF"
  ) {

    digitalWrite(
      LED_GREEN,
      LOW
    );

    digitalWrite(
      LED_RED,
      LOW
    );

    return;

  }

}


/* ==========================================
   LCD
========================================== */

void processLCDCommand(
  String command
) {

  /*
    Formato:

    LCD|LINHA 1|LINHA 2
  */


  int first =
    command.indexOf('|');

  int second =
    command.indexOf(
      '|',
      first + 1
    );


  if(
    first < 0 ||
    second < 0
  )
    return;


  String line1 =
    command.substring(
      first + 1,
      second
    );

  String line2 =
    command.substring(
      second + 1
    );


  showLCD(
    line1,
    line2
  );

}


/* ==========================================
   ESCREVER LCD
========================================== */

void showLCD(
  String line1,
  String line2
) {

  lcd.clear();


  /*
    LINHA 1
  */

  lcd.setCursor(
    0,
    0
  );

  if(
    line1.length() > 16
  ) {

    line1 =
      line1.substring(
        0,
        16
      );

  }

  lcd.print(
    line1
  );


  /*
    LINHA 2
  */

  lcd.setCursor(
    0,
    1
  );

  if(
    line2.length() > 16
  ) {

    line2 =
      line2.substring(
        0,
        16
      );

  }

  lcd.print(
    line2
  );

}
